INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'predict', 'vt.', '/prɪˈdɪkt/', '预测;预言;预料', 'Scientists predict that robots will do most housework in the future.', '科学家预测,未来机器人将承担大部分家务。', 'Looking into the Future', 1, 0, 'senior', 'wordlist', 'elective1', 'U2', 'predict the future', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'prediction', 'n.', '/prɪˈdɪkʃn/', '预测;预言', 'His prediction about smart homes has already come true.', '他对智能家居的预测已经成真。', 'Looking into the Future', 2, 0, 'senior', 'wordlist', 'elective1', 'U2', 'make a prediction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'forecast', 'vt. & n.', '/ˈfɔːkɑːst/', '预测;预报', 'Experts forecast that AI will change the way we work.', '专家预测人工智能将改变我们的工作方式。', 'Looking into the Future', 3, 0, 'senior', 'wordlist', 'elective1', 'U2', 'forecast changes', '美音 /ˈfɔːrkæst/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'prospect', 'n.', '/ˈprɒspekt/', '可能性;前景', 'Living in a fully automatic home is an exciting prospect.', '住在全自动化的家中是个令人兴奋的前景。', 'Looking into the Future', 4, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a scary prospect', '美音 /ˈprɑːspekt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'potential', 'adj. & n.', '/pəˈtenʃl/', '可能的;潜在的;潜力;可能性', 'Smart sensors can detect potential dangers before they happen.', '智能传感器能在危险发生前察觉潜在的风险。', 'Looking into the Future', 5, 0, 'senior', 'wordlist', 'elective1', 'U2', 'potential dangers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'potentially', 'adv.', '/pəˈtenʃəli/', '潜在地;可能地', 'A smart toilet could potentially save your life by finding illness early.', '智能马桶能及早发现疾病,从而可能挽救你的生命。', 'Looking into the Future', 6, 0, 'senior', 'wordlist', 'elective1', 'U2', 'potentially save lives', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'innovation', 'n.', '/ˌɪnəˈveɪʃn/', '创新;创造;新事物', 'Many of these new innovations are already being used in some homes.', '许多这样的新创造已经在一些家庭中使用了。', 'Looking into the Future', 7, 0, 'senior', 'wordlist', 'elective1', 'U2', 'new innovations', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'integrate', 'vi. & vt.', '/ˈɪntɪɡreɪt/', '(使)合并;成为一体', 'A smart home integrates computers into the structure of the building itself.', '智能家居把计算机融入了建筑本身的结构中。', 'Looking into the Future', 8, 0, 'senior', 'wordlist', 'elective1', 'U2', 'integrate into', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'integrated', 'adj.', '/ˈɪntɪɡreɪtɪd/', '各部分密切协调的;综合的', 'The future home will use integrated sensors to tell when you leave.', '未来的家会用综合传感器来判断你何时离开。', 'Looking into the Future', 9, 0, 'senior', 'wordlist', 'elective1', 'U2', 'integrated sensors', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'efficient', 'adj.', '/ɪˈfɪʃnt/', '效率高的;有功效的', 'The house goes into an energy-efficient mode all by itself.', '这座房子会自动进入节能模式。', 'Looking into the Future', 10, 0, 'senior', 'wordlist', 'elective1', 'U2', 'energy-efficient', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'constant', 'adj.', '/ˈkɒnstənt/', '不断的;重复的;不变的', 'Smart toilets keep constant track of your health every day.', '智能马桶每天持续追踪你的健康状况。', 'Looking into the Future', 11, 0, 'senior', 'wordlist', 'elective1', 'U2', 'keep constant track of', '美音 /ˈkɑːnstənt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'critical', 'adj.', '/ˈkrɪtɪkl/', '严重的;关键的;批判性的', 'The device can warn you early if you have a critical illness.', '这种设备能在你患重病时及早发出警告。', 'Looking into the Future', 12, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a critical illness', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'detect', 'vt.', '/dɪˈtekt/', '发现;查明;察觉', 'If a water pipe leaks, your smart home will detect it at once.', '如果水管漏水,你的智能家居会立刻察觉。', 'Looking into the Future', 13, 0, 'senior', 'wordlist', 'elective1', 'U2', 'detect a problem', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'sensor', 'n.', '/ˈsensə(r)/', '传感器;敏感元件', 'The home uses sensors to tell when you enter or leave the room.', '这座房子用传感器来判断你何时进出房间。', 'Looking into the Future', 14, 0, 'senior', 'wordlist', 'elective1', 'U2', 'use sensors', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'switch', 'n. & v.', '/swɪtʃ/', '开关;转换器;转换;改变', 'You will no longer have to turn switches on and off yourself.', '你再也不必自己开关那些开关了。', 'Looking into the Future', 15, 0, 'senior', 'wordlist', 'elective1', 'U2', 'switch off the TV', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'secure', 'adj. & vt.', '/sɪˈkjʊə(r)/', '安全的;牢固的;获得;保护', 'Smart homes will keep us secure and save us energy.', '智能家居会保障我们的安全并节省能源。', 'Looking into the Future', 16, 0, 'senior', 'wordlist', 'elective1', 'U2', 'keep us secure', '美音 /sɪˈkjʊr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'security', 'n.', '/sɪˈkjʊərəti/', '保护措施;安全工作', 'Cameras and sensors greatly improve home security.', '摄像头和传感器大大提升了家庭安全。', 'Looking into the Future', 17, 0, 'senior', 'wordlist', 'elective1', 'U2', 'home security', '美音 /sɪˈkjʊrəti/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'remote', 'adj.', '/rɪˈməʊt/', '远程的;偏远的', 'We can control these machines from a remote place by phone.', '我们可以用手机从远处控制这些机器。', 'Looking into the Future', 18, 0, 'senior', 'wordlist', 'elective1', 'U2', 'remote control', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'routine', 'n. & adj.', '/ruːˈtiːn/', '常规;日常生活;日常的', 'Your home will learn your daily routine and preferences.', '你的家会学会你的日常生活和偏好。', 'Looking into the Future', 19, 0, 'senior', 'wordlist', 'elective1', 'U2', 'daily routine', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'preference', 'n.', '/ˈprefrəns/', '爱好;偏爱', 'The system remembers your preferences and gets everything ready.', '系统会记住你的偏好并把一切准备好。', 'Looking into the Future', 20, 0, 'senior', 'wordlist', 'elective1', 'U2', 'learn your preferences', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'obey', 'vi. & vt.', '/əˈbeɪ/', '服从;遵守', 'All controls respond to your voice, and the home system will obey.', '所有控制都对你的语音作出反应,家居系统会照做。', 'Looking into the Future', 21, 0, 'senior', 'wordlist', 'elective1', 'U2', 'obey a command', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'command', 'n. & vt.', '/kəˈmɑːnd/', '指令;命令;控制', 'Just say aloud what you want, and the home will follow your commands.', '只要把想做的事说出来,家就会执行你的指令。', 'Looking into the Future', 22, 0, 'senior', 'wordlist', 'elective1', 'U2', 'voice commands', '美音 /kəˈmænd/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'leak', 'vi. & vt. & n.', '/liːk/', '漏;渗漏;透露;漏洞', 'If a water pipe starts to leak, the home will warn you in time.', '如果水管开始漏水,这座房子会及时提醒你。', 'Looking into the Future', 23, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a water pipe leaks', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'wire', 'n. & vt.', '/ˈwaɪə(r)/', '电线;金属丝;接通电源', 'The system can find a problem in the electrical wires before a fire.', '系统能在起火前发现电线里的问题。', 'Looking into the Future', 24, 0, 'senior', 'wordlist', 'elective1', 'U2', 'electrical wires', '美音 /ˈwaɪr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'wiring', 'n.', '/ˈwaɪərɪŋ/', '电线线路;线路系统', 'If there is a short in the electrical wiring, the home will detect it.', '如果电线线路短路,这座房子会察觉到。', 'Looking into the Future', 25, 0, 'senior', 'wordlist', 'elective1', 'U2', 'the electrical wiring', '美音 /ˈwaɪrɪŋ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'warning', 'n.', '/ˈwɔːnɪŋ/', '警告;警示;先兆', 'The smart bed will send a warning to your phone if something is wrong.', '如果出现异常,智能床会向你的手机发送警告。', 'Looking into the Future', 26, 0, 'senior', 'wordlist', 'elective1', 'U2', 'send a warning', '美音 /ˈwɔːrnɪŋ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'fantasy', 'n.', '/ˈfæntəsi/', '幻想;想象', 'This smart technology is not a fantasy but a real part of today''s life.', '这种智能技术不是幻想,而是今天生活的真实部分。', 'Looking into the Future', 27, 0, 'senior', 'wordlist', 'elective1', 'U2', 'not a fantasy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'luxury', 'n.', '/ˈlʌkʃəri/', '奢华;奢侈品', 'The Amish prefer a simple life to caring about luxuries.', '阿米什人更喜欢简单生活,而不在意奢华享受。', 'Looking into the Future', 28, 0, 'senior', 'wordlist', 'elective1', 'U2', 'care about luxuries', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'career', 'n.', '/kəˈrɪə(r)/', '职业;事业', 'I found my career as an AI designer through a social media network.', '我通过社交媒体找到了人工智能设计师的职业。', 'Looking into the Future', 29, 0, 'senior', 'wordlist', 'elective1', 'U2', 'find a career', '美音 /kəˈrɪr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'occupation', 'n.', '/ˌɒkjuˈpeɪʃn/', '职业;占领', 'Many new kinds of occupation will appear as technology develops.', '随着科技发展,许多新职业将会出现。', 'Looking into the Future', 30, 0, 'senior', 'wordlist', 'elective1', 'U2', 'a future occupation', '美音 /ˌɑːkjuˈpeɪʃn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'oppose', 'vt.', '/əˈpəʊz/', '反对;抵制;阻挠', 'Some people oppose the idea of developing driverless cars.', '有些人反对发展无人驾驶汽车的想法。', 'Looking into the Future', 31, 0, 'senior', 'wordlist', 'elective1', 'U2', 'oppose the idea', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'resist', 'vi. & vt.', '/rɪˈzɪst/', '抵制;反抗;抵挡', 'I will accept new technology rather than resist it.', '我会接受新技术,而不是抵制它。', 'Looking into the Future', 32, 0, 'senior', 'wordlist', 'elective1', 'U2', 'resist change', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'resistance', 'n.', '/rɪˈzɪstəns/', '抵制;反对;抗拒', 'New technology often meets some resistance at first.', '新技术起初常常遇到一些抵制。', 'Looking into the Future', 33, 0, 'senior', 'wordlist', 'elective1', 'U2', 'meet resistance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cease', 'vi. & vt.', '/siːs/', '(使)停止;终止', 'We should not cease accepting technology just because it is new.', '我们不该仅仅因为技术是新的就停止接受它。', 'Looking into the Future', 34, 0, 'senior', 'wordlist', 'elective1', 'U2', 'cease doing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'deceased', 'adj.', '/dɪˈsiːst/', '已死的;亡故的', 'The families of the deceased said the apology was not enough.', '死者的家属表示道歉还不够。', 'Looking into the Future', 35, 0, 'senior', 'wordlist', 'elective1', 'U2', 'the families of the deceased', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'rural', 'adj.', '/ˈrʊərəl/', '乡村的;农村的', 'The Amish are a group of people living in rural America.', '阿米什人是一群生活在美国乡村的人。', 'Looking into the Future', 36, 0, 'senior', 'wordlist', 'elective1', 'U2', 'rural America', '美音 /ˈrʊrəl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'emphasis', 'n.', '/ˈemfəsɪs/', '强调;重视;重要性', 'They live a simple life with an emphasis on hard work and family.', '他们过着简单的生活,重视勤劳和家庭。', 'Looking into the Future', 37, 0, 'senior', 'wordlist', 'elective1', 'U2', 'an emphasis on', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'relevant', 'adj.', '/ˈreləvənt/', '有关的;有意义的', 'The home will give you all the relevant information about the problem.', '这座房子会向你提供关于问题的所有相关信息。', 'Looking into the Future', 38, 0, 'senior', 'wordlist', 'elective1', 'U2', 'relevant information', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'distant', 'adj.', '/ˈdɪstənt/', '遥远的;远处的;疏远的', 'In the not-too-distant future, we will be living in smart homes.', '在不太遥远的将来,我们将住在智能家居里。', 'Looking into the Future', 39, 0, 'senior', 'wordlist', 'elective1', 'U2', 'the distant future', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'instant', 'n. & adj.', '/ˈɪnstənt/', '瞬间;片刻;立即的', 'Your lights will come on the instant you enter the door.', '你一进门,灯就会立刻亮起。', 'Looking into the Future', 40, 0, 'senior', 'wordlist', 'elective1', 'U2', 'the instant you enter', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'mode', 'n.', '/məʊd/', '模式;方式;风格', 'The car crashed while it was in driverless mode.', '那辆车在无人驾驶模式下发生了碰撞。', 'Looking into the Future', 41, 0, 'senior', 'wordlist', 'elective1', 'U2', 'driverless mode', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'structure', 'n. & vt.', '/ˈstrʌktʃə(r)/', '结构;体系;精心组织', 'A smart home builds computers into the structure of the building.', '智能家居把计算机建入建筑的结构之中。', 'Looking into the Future', 42, 0, 'senior', 'wordlist', 'elective1', 'U2', 'the structure of the building', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'combine', 'vt. & vi.', '/kəmˈbaɪn/', '(使)结合;混合', 'Designers combine new sensors and software to make homes smarter.', '设计师把新传感器和软件结合起来,让家更智能。', 'Looking into the Future', 43, 0, 'senior', 'wordlist', 'elective1', 'U2', 'combine A and B', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'hence', 'adv.', '/hens/', '因此;由此', 'Some advances may be dangerous; hence we should be careful.', '有些进步可能很危险,因此我们应当谨慎。', 'Looking into the Future', 44, 0, 'senior', 'wordlist', 'elective1', 'U2', 'hence we should', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'nevertheless', 'adv.', '/ˌnevəðəˈles/', '尽管如此;不过;然而', 'Change can be scary; nevertheless, I always look on the positive side.', '改变可能令人害怕;尽管如此,我总是看积极的一面。', 'Looking into the Future', 45, 0, 'senior', 'wordlist', 'elective1', 'U2', 'nevertheless', '美音 /ˌnevərðəˈles/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'essay', 'n.', '/ˈeseɪ/', '文章', 'He is writing an essay on the pros and cons of new technology.', '他正在写一篇关于新技术利弊的文章。', 'Looking into the Future', 46, 0, 'senior', 'wordlist', 'elective1', 'U2', 'write an essay', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'advance', 'n. & vi.', '/ədˈvɑːns/', '进步;前进;发展', 'New advances in technology have brought people many benefits.', '技术上的新进步给人们带来了许多好处。', 'Looking into the Future', 47, 0, 'senior', 'wordlist', 'elective1', 'U2', 'advances in technology', '美音 /ədˈvæns/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'automatic', 'adj.', '/ˌɔːtəˈmætɪk/', '自动的;无意识的', 'We will use technology for the automatic control of our whole home.', '我们将用技术来自动控制整个家。', 'Looking into the Future', 48, 0, 'senior', 'wordlist', 'elective1', 'U2', 'automatic control', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u2.01', '①表将来某一时刻正在进行(this time tomorrow / at 8 pm tonight)', 'A2', 11, '选择性必修一 U2 — 带明确将来时间点(this time next year / at 9 am tomorrow)时,表示届时正在进行的动作,用 will be doing。', 1, 'elective1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u2.02', '②表预计必将发生 / 委婉询问(I''ll be seeing him soon / Will you be using it?)', 'A2', 11, '选择性必修一 U2 — 表示按计划或自然趋势必将发生的将来动作,或委婉地询问对方安排,用 will be doing。', 2, 'elective1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u2.03', '③与一般将来时 will do / 现在进行时 is doing 对照,凸显''将来进行''', 'A2', 11, '选择性必修一 U2 — 在同一将来时间框架下,与表''单纯将来''的 will do、''眼下正进行''的 is doing 等对比,题干的将来时间状语决定只能用 will be doing。', 3, 'elective1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'This time tomorrow, I ____ on a plane to the future technology fair.', 'will be flying', 'will fly', 'am flying', 'have flown', 'A', 'this time tomorrow 指明将来某一时刻正在进行 → will be flying。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At 8 pm tonight, the family ____ dinner cooked by their new robot.', 'will have', 'will be having', 'is having', 'has had', 'B', 'at 8 pm tonight 为将来时间点,届时动作进行中 → will be having。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'This time next year, she ____ artificial intelligence at a top university.', 'will study', 'is studying', 'will be studying', 'has studied', 'C', 'this time next year 指将来某刻正在进行 → will be studying。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At 9 am next Monday, the engineers ____ the new driverless car.', 'will test', 'are testing', 'have tested', 'will be testing', 'D', 'at 9 am next Monday 为将来时间点 → will be testing。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'When you arrive tomorrow, the smart home ____ everything ready for you.', 'will be getting', 'will get', 'is getting', 'has got', 'A', 'when you arrive tomorrow 指明将来某刻动作进行中 → will be getting。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At midnight tonight, the sensors ____ the temperature of every room.', 'will check', 'will be checking', 'are checking', 'have checked', 'B', 'at midnight tonight 为将来时间点 → will be checking。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'This time next week, we ____ in a fully automatic house.', 'will live', 'are living', 'will be living', 'have lived', 'C', 'this time next week 指将来某刻进行中 → will be living。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At 7 am tomorrow, the robot ____ breakfast while you are still asleep.', 'will prepare', 'is preparing', 'has prepared', 'will be preparing', 'D', 'at 7 am tomorrow 为将来时间点、强调进行 → will be preparing。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'By this time tomorrow, the scientists ____ their predictions on the radio.', 'will be sharing', 'will share', 'are sharing', 'have shared', 'A', 'by this time tomorrow 指将来某刻动作进行中 → will be sharing。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At 3 pm next Friday, the students ____ about the future of technology.', 'will talk', 'will be talking', 'are talking', 'have talked', 'B', 'at 3 pm next Friday 为将来时间点 → will be talking。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'This time tomorrow morning, the smart bed ____ how well you slept.', 'will record', 'is recording', 'will be recording', 'has recorded', 'C', 'this time tomorrow morning 指将来某刻进行中 → will be recording。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'When the show opens next month, robots ____ tea to the visitors.', 'will serve', 'are serving', 'have served', 'will be serving', 'D', 'when the show opens next month 指明将来某刻动作进行中 → will be serving。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At noon tomorrow, the home system ____ the lights to save energy.', 'will be switching', 'will switch', 'is switching', 'has switched', 'A', 'at noon tomorrow 为将来时间点 → will be switching。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'This time next year, more people ____ in driverless cars to work.', 'will travel', 'will be travelling', 'are travelling', 'have travelled', 'B', 'this time next year 指将来某刻进行中 → will be travelling。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At 10 am tomorrow, the doctor ____ a patient with the help of nanobots.', 'will treat', 'is treating', 'will be treating', 'has treated', 'C', 'at 10 am tomorrow 为将来时间点、强调进行 → will be treating。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'This time on Sunday, the family ____ a film chosen by their AI assistant.', 'will watch', 'are watching', 'have watched', 'will be watching', 'D', 'this time on Sunday 指将来某刻进行中 → will be watching。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At 6 pm tomorrow, the toilet ____ track of grandpa''s health as usual.', 'will be keeping', 'will keep', 'is keeping', 'has kept', 'A', 'at 6 pm tomorrow 为将来时间点 → will be keeping。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'When we land in Beijing next week, our smart house ____ the door for us.', 'will lock', 'will be locking', 'is locking', 'has locked', 'B', 'when we land next week 指将来某刻动作进行中 → will be locking。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'At this moment next month, the team ____ on their new RoboBee project.', 'will work', 'are working', 'will be working', 'have worked', 'C', 'at this moment next month 指将来某刻进行中 → will be working。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.01'), 'By 9 o''clock tomorrow, the sensors ____ data from every smart device.', 'will collect', 'are collecting', 'have collected', 'will be collecting', 'D', 'by 9 o''clock tomorrow 指将来某刻动作进行中 → will be collecting。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'Don''t worry about the time — I ____ you at the airport tomorrow anyway.', 'will be meeting', 'will meet', 'am meeting', 'have met', 'A', '表预计必将发生的将来安排,语气委婉 → will be meeting。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), '____ you ____ the computer tonight, or may I borrow it for my essay?', 'Will / use', 'Will / be using', 'Are / using', 'Have / used', 'B', '委婉询问对方今晚的安排 → Will you be using …?', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'I ____ him soon, so I''ll pass on your message about the project.', 'will see', 'am seeing', 'will be seeing', 'have seen', 'C', '表预计必将发生的将来动作,语气自然 → will be seeing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), '____ you ____ the car this weekend? If not, I''d like to test the new mode.', 'Will / use', 'Are / using', 'Have / used', 'Will / be using', 'D', '委婉询问对方周末的安排 → Will you be using …?', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'The company says most people ____ in driverless cars one day soon.', 'will be travelling', 'will travel', 'are travelling', 'have travelled', 'A', '表预计必将发生的将来趋势 → will be travelling。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'Just leave it to me — I ____ past the shop later, so I''ll buy the sensor.', 'will go', 'will be going', 'am going', 'have gone', 'B', '表预计顺道必将发生的将来动作 → will be going。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), '____ you ____ the meeting room after lunch? We need it for a robot demo.', 'Will / need', 'Are / needing', 'Will / be needing', 'Have / needed', 'C', '委婉询问对方午饭后的安排 → Will you be needing …?', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'I ____ Dr Han at the fair next week, so I''ll ask about her predictions.', 'will visit', 'am visiting', 'have visited', 'will be visiting', 'D', '表预计必将发生的将来安排 → will be visiting。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'Don''t call at nine — the family ____ their evening health check then.', 'will be doing', 'will do', 'are doing', 'have done', 'A', '表预计届时必将进行的日常 → will be doing。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), '____ you ____ your headset later? I''d like to try the virtual reality tour.', 'Will / wear', 'Will / be wearing', 'Are / wearing', 'Have / worn', 'B', '委婉询问对方稍后的安排 → Will you be wearing …?', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'Relax — the smart home ____ care of the lights, so you needn''t return.', 'will take', 'is taking', 'will be taking', 'has taken', 'C', '表预计必将发生、语气安抚的将来动作 → will be taking。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'I ____ the new app all next week, so I can show you how it works.', 'will test', 'am testing', 'have tested', 'will be testing', 'D', '表预计必将持续进行的将来安排 → will be testing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), '____ the robots ____ at the fair, or are they only on display this year?', 'Will / be working', 'Will / work', 'Are / working', 'Have / worked', 'A', '委婉询问将来的安排 → Will the robots be working …?', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'By the look of it, we ____ AI in almost every job before long.', 'will use', 'will be using', 'are using', 'have used', 'B', '表预计必将发生的将来趋势 → will be using。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'Leave the parcel with me — I ____ the neighbour this evening anyway.', 'will see', 'am seeing', 'will be seeing', 'have seen', 'C', '表预计顺便必将发生的将来动作 → will be seeing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), '____ you ____ the printer this afternoon? I need to print my report.', 'Will / use', 'Are / using', 'Have / used', 'Will / be using', 'D', '委婉询问对方下午的安排 → Will you be using …?', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'The forecast says we ____ many small robots working together by 2030.', 'will be seeing', 'will see', 'are seeing', 'have seen', 'A', '表预计必将发生的将来情景 → will be seeing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'Don''t hurry — the sensors ____ the data while we have our coffee.', 'will collect', 'will be collecting', 'are collecting', 'have collected', 'B', '表预计届时必将进行的将来动作 → will be collecting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), 'I ____ past your office tomorrow, so I can drop off the smart watch.', 'will pass', 'am passing', 'will be passing', 'have passed', 'C', '表预计顺道必将发生的将来动作 → will be passing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.02'), '____ the lab ____ visitors next month, or is it closed for the upgrade?', 'Will / welcome', 'Is / welcoming', 'Has / welcomed', 'Will / be welcoming', 'D', '委婉询问将来的安排 → Will the lab be welcoming …?', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'Compare these: tomorrow he ____ a robot, but right now he just dreams of it.', 'will be building', 'will build', 'is building', 'has built', 'A', 'tomorrow 强调将来某刻进行中,对照''眼下''的现在进行 → will be building。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'At this time tomorrow we ____ the show, while today we are only planning it.', 'will watch', 'will be watching', 'are watching', 'have watched', 'B', 'at this time tomorrow 凸显将来进行,区别于今天的 are planning → will be watching。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'Next Monday at noon the team ____ the new car; they don''t test it today.', 'will test', 'is testing', 'will be testing', 'has tested', 'C', 'next Monday at noon 为将来时间点,凸显将来进行 → will be testing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'This time next week she ____ in Beijing; she is still in Melbourne now.', 'will work', 'is working', 'has worked', 'will be working', 'D', 'this time next week 强调将来某刻进行,对照''现在''的 is working → will be working。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'When you wake up tomorrow, the home ____ your coffee, not making it now.', 'will be making', 'will make', 'is making', 'has made', 'A', 'when you wake up tomorrow 指将来某刻进行中,区别于现在 → will be making。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'At 8 tomorrow the sensors ____ the air; right now they are switched off.', 'will check', 'will be checking', 'are checking', 'have checked', 'B', 'at 8 tomorrow 为将来时间点,凸显将来进行 → will be checking。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'This time next year robots ____ our streets, though few do so today.', 'will clean', 'are cleaning', 'will be cleaning', 'have cleaned', 'C', 'this time next year 强调将来某刻进行,对照今天 → will be cleaning。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'At 9 pm tomorrow the bed ____ his sleep, not watching it at the moment.', 'will track', 'is tracking', 'has tracked', 'will be tracking', 'D', 'at 9 pm tomorrow 为将来时间点,凸显将来进行 → will be tracking。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'When the fair starts next week, AI designers ____ their latest ideas.', 'will be showing', 'will show', 'are showing', 'have shown', 'A', 'when the fair starts next week 指将来某刻进行中 → will be showing。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'By this time tomorrow the city ____ traffic by computer, unlike today.', 'will control', 'will be controlling', 'is controlling', 'has controlled', 'B', 'by this time tomorrow 强调将来某刻进行,对照今天 → will be controlling。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'At 7 tomorrow evening she ____ her report, while now she just reads notes.', 'will write', 'is writing', 'will be writing', 'has written', 'C', 'at 7 tomorrow evening 为将来时间点,凸显将来进行 → will be writing。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'This time next month the nanobots ____ inside patients to fight illness.', 'will work', 'are working', 'have worked', 'will be working', 'D', 'this time next month 强调将来某刻进行 → will be working。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'When classes begin next term, students ____ AI to study, not paper books.', 'will be using', 'will use', 'are using', 'have used', 'A', 'when classes begin next term 指将来某刻进行中 → will be using。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'At noon tomorrow the kitchen ____ lunch by itself; it doesn''t do so now.', 'will cook', 'will be cooking', 'is cooking', 'has cooked', 'B', 'at noon tomorrow 为将来时间点,凸显将来进行 → will be cooking。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'This time on Friday they ____ to the moon base; today they only train.', 'will fly', 'are flying', 'will be flying', 'have flown', 'C', 'this time on Friday 强调将来某刻进行,对照今天 → will be flying。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'At 10 tomorrow the smart home ____ the wiring; it isn''t doing that now.', 'will check', 'is checking', 'has checked', 'will be checking', 'D', 'at 10 tomorrow 为将来时间点,凸显将来进行 → will be checking。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'When we meet next week, the company ____ its newest robot to the public.', 'will be presenting', 'will present', 'is presenting', 'has presented', 'A', 'when we meet next week 指将来某刻进行中 → will be presenting。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'By 8 tomorrow morning the system ____ energy, while now it wastes some.', 'will save', 'will be saving', 'is saving', 'has saved', 'B', 'by 8 tomorrow morning 强调将来某刻进行,对照现在 → will be saving。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'At this hour next week the doctors ____ the data; today they collect it.', 'will study', 'are studying', 'will be studying', 'have studied', 'C', 'at this hour next week 为将来时间点,凸显将来进行 → will be studying。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U2' AND code='e1u2.03'), 'When the upgrade ends tomorrow, the cars ____ themselves on the roads.', 'will drive', 'are driving', 'have driven', 'will be driving', 'D', 'when the upgrade ends tomorrow 指将来某刻进行中 → will be driving。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Smart Homes to Make Life Easier', 'Have you ever forgotten to lock the door of your house, or to switch off the TV before leaving? These small things happen to all of us, and they often waste energy and sometimes cause real trouble. In the not-too-distant future, however, we will be living in smart homes that take care of such problems for us. A smart home builds computers into the structure of the building itself, so it can lock the door when we are away and switch off devices when we forget. Using integrated sensors, the home can tell the moment you leave each morning, and then go into an energy-saving mode all by itself. It will also learn your daily routine and preferences, so the lights, music and even dinner will be ready the instant you walk in. All of this keeps us secure, saves us energy, and makes life far more comfortable than it is today.', '说明·智能家居', 152, '[{"q":"What problem does the writer mention at the beginning?","answer":"A","options":["People sometimes forget to lock doors or turn off devices.","Smart homes are too expensive for ordinary families.","Computers in houses break down very often.","People do not know how to use new technology."],"explanation":"开头举''忘锁门、忘关电视''为例,选项是其概括转述。"},{"q":"How does a smart home know when you have gone out?","answer":"B","options":["It calls your phone to check on you.","It uses built-in sensors to notice you leaving.","It asks a neighbour to watch the door.","It waits until the evening to find out."],"explanation":"原文 ''using integrated sensors, the home can tell the moment you leave'' 的转述。"},{"q":"According to the text, what are the benefits of a smart home?","answer":"A","options":["It keeps us safe, saves energy and adds comfort.","It makes houses look more beautiful.","It helps people get more exercise.","It teaches children how to cook dinner."],"explanation":"末句 ''keeps us secure, saves us energy, and makes life far more comfortable'' 的转述。"}]'::jsonb, '[{"word":"secure","cn":"安全的"},{"word":"routine","cn":"日常生活"},{"word":"sensor","cn":"传感器"}]'::jsonb, 2, 'elective1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Should We Fight Driverless Cars?', 'One morning I read a shocking headline about a passenger who died when a car crashed in driverless mode. In the report, several people argued that the public should oppose the idea of developing such cars, saying that some advances in technology are unnecessary and even dangerous. The car company apologised for the accident, but the families of the deceased felt that an apology was not enough. The company still claimed that most people would be travelling in driverless cars before long. On the one hand, fewer human mistakes might mean fewer accidents, since a tired or careless driver is often the real cause of a crash. On the other hand, no machine is perfect, and people worry about who is to blame when something goes wrong. Hence, the debate is not really about whether the cars are clever enough; it is about how much we are willing to trust them with our lives. Personally, I believe we should test such technology carefully rather than simply reject it.', '议论·无人驾驶利弊', 168, '[{"q":"Why did some people in the report want to stop driverless cars?","answer":"B","options":["They thought the cars were too slow.","They believed such advances could be needless and unsafe.","They could not afford to buy one.","They preferred riding bicycles instead."],"explanation":"原文 ''some advances in technology are unnecessary and even dangerous'' 的转述。"},{"q":"What is one possible advantage of driverless cars mentioned in the text?","answer":"C","options":["They never need any repair.","They are completely free to use.","They could reduce accidents caused by human error.","They can fly over busy cities."],"explanation":"原文 ''fewer human mistakes might mean fewer accidents'' 的转述。"},{"q":"What is the writer''s own opinion at the end?","answer":"D","options":["Driverless cars should be banned at once.","The cars are already perfect.","Nobody should drive any car ever again.","We should test the technology with care, not reject it."],"explanation":"末句 ''test such technology carefully rather than simply reject it'' 的转述。"}]'::jsonb, '[{"word":"oppose","cn":"反对"},{"word":"deceased","cn":"亡故的"},{"word":"hence","cn":"因此"}]'::jsonb, 2, 'elective1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'New Jobs in an Age of AI', 'Whenever people hear that machines are getting smarter, many of them start to worry about their jobs. It is true that artificial intelligence will take over some routine work, such as checking numbers or sorting parcels. Yet history shows that new technology usually creates more careers than it removes. When cars replaced horses, for example, whole new occupations appeared, from car designers to road builders. The same thing is likely to happen again. In the coming years we will be needing people who can design, repair and teach these clever machines, as well as people who do the warm, human jobs that no robot can copy, such as caring for the old or comforting the sick. The real lesson is not to fear the change, but to prepare for it. Students today should learn how to work together with smart machines instead of competing against them. Those who do so will find that the future of work is full of fresh chances rather than empty fears.', '说明·人工智能与职业', 166, '[{"q":"What kind of work will AI most likely take over?","answer":"A","options":["Simple, repeated tasks like checking numbers.","Caring for old or sick people.","Designing brand-new machines.","Comforting people who feel sad."],"explanation":"原文 ''take over some routine work, such as checking numbers or sorting parcels'' 的转述。"},{"q":"What does the example of cars replacing horses show?","answer":"B","options":["New technology destroys all old jobs.","New technology can open up fresh occupations.","People should never accept change.","Horses were better than cars."],"explanation":"原文 ''whole new occupations appeared, from car designers to road builders'' 的转述。"},{"q":"What advice does the writer give to students?","answer":"C","options":["Avoid all jobs that use machines.","Stop studying science and maths.","Team up with clever machines instead of fighting them.","Compete against robots as hard as possible."],"explanation":"原文 ''learn how to work together with smart machines instead of competing against them'' 的转述。"}]'::jsonb, '[{"word":"routine","cn":"常规的"},{"word":"occupation","cn":"职业"},{"word":"career","cn":"职业"}]'::jsonb, 2, 'elective1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'A Walk Through the Future City', 'Imagine waking up one morning in the city of 2050. The curtains open by themselves as the sun rises, and a soft voice tells you the weather forecast for the day. You step outside, and a driverless bus stops quietly to pick you up, choosing the fastest route through streets with no traffic jams. Sensors in the road send information to a central computer, which controls the lights so that cars and buses keep moving smoothly. Tall buildings are covered with plants that clean the air and keep the city cool. At lunchtime you visit a small shop where a friendly robot prepares your meal, while drones carry parcels above your head. None of this feels strange to the people who live here, because the technology has grown up slowly around them. In this sense, the city of tomorrow is simply the city of today with many small, clever improvements added one step at a time.', '记叙·未来城市一日', 156, '[{"q":"How does the driverless bus choose its way through the city?","answer":"D","options":["It follows the same fixed route every day.","It waits for a human driver to decide.","It always takes the longest road.","It picks the quickest path with no traffic jams."],"explanation":"原文 ''choosing the fastest route through streets with no traffic jams'' 的转述。"},{"q":"Why are the tall buildings covered with plants?","answer":"A","options":["To clean the air and cool the city.","To make them look taller.","To hide the windows from the sun.","To grow food for the robots."],"explanation":"原文 ''plants that clean the air and keep the city cool'' 的转述。"},{"q":"Why does none of this feel strange to the people there?","answer":"B","options":["They were all born in another country.","The technology appeared gradually as they grew up.","They never leave their homes.","They do not notice the technology at all."],"explanation":"原文 ''the technology has grown up slowly around them'' 的转述。"}]'::jsonb, '[{"word":"forecast","cn":"预报"},{"word":"remote","cn":"远程的"},{"word":"structure","cn":"结构"}]'::jsonb, 2, 'elective1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Tiny Robots, Big Hopes', 'Some of the most exciting future technology is also the smallest. Scientists are now developing nanobots, robots so tiny that thousands of them could fit on the head of a pin. One day, doctors may send these little machines into the human body to do jobs that are too delicate for ordinary tools. A nanobot could travel through the blood, detect a problem early, and even carry medicine straight to a sick part of the body. Because the robot works only where it is needed, it could potentially cause far less harm than today''s treatments. Tiny robots might also help repair damage that doctors cannot reach now, giving fresh hope to many patients. Of course, this technology is still being tested, and there are many questions to answer about safety. Nevertheless, researchers believe that within our lifetimes these clever machines will be playing an important part in keeping people healthy, working quietly inside us where no one can see them.', '说明·纳米机器人与健康', 160, '[{"q":"What are nanobots, according to the passage?","answer":"C","options":["Large machines used in factories.","A new kind of mobile phone.","Extremely small robots, thousands of which fit on a pin head.","Robots that drive cars on the road."],"explanation":"原文 ''robots so tiny that thousands of them could fit on the head of a pin'' 的转述。"},{"q":"Why might nanobots cause less harm than today''s treatments?","answer":"D","options":["Because they are made of cheap metal.","Because they work for a very short time.","Because they are controlled by patients themselves.","Because they only act where they are actually needed."],"explanation":"原文 ''the robot works only where it is needed, it could … cause far less harm'' 的转述。"},{"q":"What does the writer say about the safety of this technology?","answer":"A","options":["There are still safety questions to answer.","It is already perfectly safe.","It will never be safe enough.","Safety does not matter at all."],"explanation":"原文 ''there are many questions to answer about safety'' 的转述。"}]'::jsonb, '[{"word":"detect","cn":"察觉"},{"word":"potentially","cn":"可能地"},{"word":"nevertheless","cn":"尽管如此"}]'::jsonb, 2, 'elective1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Living Without New Technology', 'Not everyone welcomes new technology, and some people choose to live without it on purpose. The best known of these are the Amish, a group living in rural America. They do not own cars, watch TV, or use the Internet, and they have farmed the land in much the same way since the eighteenth century. They place a strong emphasis on hard work, family and community, and they believe this matters far more than chasing luxuries or following the lives of the rich and famous. Some people argue that the quality of their life is actually better, because they live close to nature instead of in large, polluted cities. Their example reminds us of an important point: more technology does not always mean a happier life. Even those of us who love new machines can learn something from such communities. The real question for the future is not how much technology we can build, but how wisely we choose to use the technology we already have.', '说明·拒绝新科技的人群', 166, '[{"q":"How do the Amish live, according to the text?","answer":"B","options":["They use the newest cars and computers.","They farm the land much as they did long ago.","They move from city to city every year.","They spend most of their time watching TV."],"explanation":"原文 ''they have farmed the land in much the same way since the eighteenth century'' 的转述。"},{"q":"What do the Amish value most?","answer":"C","options":["Expensive luxuries and fame.","The fastest new machines.","Working hard and staying close to family.","Travelling around the world."],"explanation":"原文 ''a strong emphasis on hard work, family and community'' 的转述。"},{"q":"What is the main lesson the writer draws from their example?","answer":"D","options":["Everyone should give up technology completely.","City life is always worse than country life.","We must build as much technology as possible.","Having more machines will not always bring greater happiness."],"explanation":"原文 ''more technology does not always mean a happier life'' 的转述。"}]'::jsonb, '[{"word":"rural","cn":"乡村的"},{"word":"emphasis","cn":"重视"},{"word":"luxury","cn":"奢华"}]'::jsonb, 2, 'elective1', 'U2');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U2', 'My Smart Alarm Clock', 'Last week my parents bought a smart alarm clock, and it has completely changed my morning (1)____. Instead of ringing loudly, it slowly turns up the light, so I wake up feeling (2)____ rather than shocked. While I am still in bed, it quietly tells me the weather (3)____ for the day. If the roads are busy, it will (4)____ me to leave home a little earlier. The clock has learned my (5)____, so it knows that I like soft music in the morning. It is also connected to the kitchen, and it can (6)____ on the coffee machine before I get up. At first I thought such a clock was just a silly (7)____, but now I find it really (8)____. It saves me time and helps me feel (9)____ during the day. Thanks to this little machine, I am never (10)____ for school any more.', 147, 2, '[{"q":"1","answer":"A","options":["routine","garden","noise","ticket"],"explanation":"morning routine 早晨的日常。"},{"q":"2","answer":"B","options":["angry","calm","afraid","bored"],"explanation":"wake up feeling calm 醒来感到平静。"},{"q":"3","answer":"C","options":["price","song","forecast","shop"],"explanation":"weather forecast 天气预报。"},{"q":"4","answer":"D","options":["forget","lose","sell","warn"],"explanation":"warn me to leave earlier 提醒我早点出门。"},{"q":"5","answer":"A","options":["preferences","mistakes","buildings","machines"],"explanation":"learned my preferences 了解我的偏好。"},{"q":"6","answer":"B","options":["break","switch","throw","drop"],"explanation":"switch on the coffee machine 打开咖啡机。"},{"q":"7","answer":"C","options":["price","garden","fantasy","market"],"explanation":"a silly fantasy 愚蠢的幻想。"},{"q":"8","answer":"D","options":["empty","wrong","late","useful"],"explanation":"really useful 真的有用。"},{"q":"9","answer":"A","options":["secure","hungry","tired","sorry"],"explanation":"feel secure 感到安心。"},{"q":"10","answer":"B","options":["rich","late","busy","quiet"],"explanation":"never late for school 上学再没迟到。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U2', 'The Robot Helper at School', 'This year our school got its first robot (1)____, and the students love it. The robot can move around the library and help us (2)____ the books we need. If you ask a question, it will give you a quick and (3)____ answer in a friendly voice. It uses small (4)____ to know where people are, so it never bumps into anyone. Some teachers worried that the robot would (5)____ their jobs, but that did not happen. Instead, it does the boring (6)____ work, such as putting books back, so the teachers have more time to (7)____ us. At first a few students wanted to (8)____ the idea, but soon they changed their minds. Now the robot is the most popular (9)____ at school. In the future, we will probably be (10)____ together with such machines every day.', 138, 2, '[{"q":"1","answer":"C","options":["price","noise","helper","garden"],"explanation":"a robot helper 机器人助手。"},{"q":"2","answer":"D","options":["eat","throw","sell","find"],"explanation":"help us find the books 帮我们找书。"},{"q":"3","answer":"A","options":["relevant","empty","rude","late"],"explanation":"a relevant answer 切题的回答。"},{"q":"4","answer":"B","options":["prices","sensors","songs","tickets"],"explanation":"small sensors 小型传感器。"},{"q":"5","answer":"C","options":["sing","open","take","wash"],"explanation":"take their jobs 抢走他们的工作。"},{"q":"6","answer":"D","options":["happy","rich","polite","routine"],"explanation":"the boring routine work 无聊的日常工作。"},{"q":"7","answer":"A","options":["help","forget","lose","sell"],"explanation":"more time to help us 更多时间帮我们。"},{"q":"8","answer":"B","options":["enjoy","resist","welcome","trust"],"explanation":"resist the idea 抵制这个想法。"},{"q":"9","answer":"C","options":["price","market","helper","shop"],"explanation":"the most popular helper 最受欢迎的助手。"},{"q":"10","answer":"D","options":["losing","selling","hiding","working"],"explanation":"be working together with such machines 和这些机器一起工作。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U2', 'A Kitchen That Listens', 'My uncle''s new kitchen can understand (1)____ commands, which still amazes me. When he wants the lights on, he just (2)____ aloud what he wants, and the kitchen will (3)____. He can ask it to warm the oven or play music while he cooks. The kitchen uses clever (4)____ to know when the food is ready, so nothing ever gets burned. If a water pipe starts to (5)____, the system will (6)____ the problem at once and send a (7)____ to his phone. My uncle says this technology is no longer a (8)____; it is part of everyday life. He believes that in the near future, most homes will be (9)____ such smart systems. For now, I just enjoy watching the kitchen do its work all by (10)____.', 128, 2, '[{"q":"1","answer":"A","options":["voice","price","garden","ticket"],"explanation":"voice commands 语音指令。"},{"q":"2","answer":"B","options":["eats","says","throws","sells"],"explanation":"says aloud what he wants 把想做的事说出来。"},{"q":"3","answer":"C","options":["sleep","cry","obey","leave"],"explanation":"the kitchen will obey 厨房会照做。"},{"q":"4","answer":"D","options":["prices","songs","noises","sensors"],"explanation":"clever sensors 灵敏的传感器。"},{"q":"5","answer":"A","options":["leak","sing","smile","dance"],"explanation":"starts to leak 开始漏水。"},{"q":"6","answer":"B","options":["detect","forget","sell","lose"],"explanation":"detect the problem 察觉问题。"},{"q":"7","answer":"C","options":["price","song","warning","game"],"explanation":"send a warning 发出警告。"},{"q":"8","answer":"D","options":["price","shop","city","fantasy"],"explanation":"no longer a fantasy 不再是幻想。"},{"q":"9","answer":"A","options":["using","losing","selling","hiding"],"explanation":"be using such smart systems 使用这样的智能系统。"},{"q":"10","answer":"B","options":["someone","itself","nobody","anyone"],"explanation":"all by itself 全靠自己。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U2', 'The Doctor of the Future', 'In the future, going to see a doctor may be very (1)____ from today. You might not even leave your home. Instead, a small machine on your wrist will keep (2)____ track of your health all day long. If it (3)____ that something is wrong, it will (4)____ you a message at once. A doctor far away can then look at your information through a (5)____ link and decide what to do. For a serious or (6)____ illness, tiny robots might even be sent into your body to carry (7)____ to exactly the right place. Such treatment could (8)____ save many lives. Of course, this kind of care is still being (9)____, and we must make sure it is safe. (10)____, many doctors believe it will soon become a normal part of medicine.', 133, 2, '[{"q":"1","answer":"C","options":["happy","rich","different","polite"],"explanation":"very different from today 与今天大不相同。"},{"q":"2","answer":"D","options":["price","song","ticket","constant"],"explanation":"keep constant track 持续追踪。"},{"q":"3","answer":"A","options":["detects","sells","eats","throws"],"explanation":"if it detects something wrong 如果它察觉异常。"},{"q":"4","answer":"B","options":["lose","send","forget","sell"],"explanation":"send you a message 给你发消息。"},{"q":"5","answer":"C","options":["happy","rich","remote","late"],"explanation":"a remote link 远程连接。"},{"q":"6","answer":"D","options":["empty","polite","quiet","critical"],"explanation":"a critical illness 重病。"},{"q":"7","answer":"A","options":["medicine","noise","price","weather"],"explanation":"carry medicine 携带药物。"},{"q":"8","answer":"B","options":["never","potentially","hardly","seldom"],"explanation":"potentially save many lives 可能挽救许多生命。"},{"q":"9","answer":"C","options":["sold","lost","tested","eaten"],"explanation":"still being tested 仍在测试中。"},{"q":"10","answer":"D","options":["Because","Although","Unless","Nevertheless"],"explanation":"Nevertheless 尽管如此(句首副词)。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U2', 'The Smart Umbrella', 'One rainy evening, my smart umbrella saved my day. Before I left the office, it checked the weather (1)____ and told me a storm was coming. As I walked outside, small (2)____ in the handle felt the wind and held the umbrella (3)____ against it, so it never turned inside out. When the rain grew heavy, a soft light came on the (4)____ I needed it, helping me see the dark path. The umbrella was also connected to my phone, so it could (5)____ me if I was about to leave it behind on the bus. My friends thought a clever umbrella was just a (6)____ at first, but they soon wanted one too. It is amazing how a (7)____ object can become so useful. In the near future, we will probably be (8)____ many such smart things every day. They make life safer, more (9)____, and a little more fun. For me, the rainy walk home was no longer a (10)____ at all.', 164, 2, '[{"q":"1","answer":"A","options":["forecast","garden","price","shop"],"explanation":"weather forecast 天气预报。"},{"q":"2","answer":"B","options":["prices","sensors","songs","tickets"],"explanation":"small sensors 小型传感器。"},{"q":"3","answer":"C","options":["empty","late","secure","rich"],"explanation":"held it secure 把它牢牢撑稳。"},{"q":"4","answer":"D","options":["price","noise","garden","instant"],"explanation":"the instant I needed it 我一需要它就……。"},{"q":"5","answer":"A","options":["warn","forget","sell","lose"],"explanation":"warn me 提醒我。"},{"q":"6","answer":"B","options":["price","fantasy","city","market"],"explanation":"just a fantasy 不过是幻想。"},{"q":"7","answer":"C","options":["loud","angry","simple","rude"],"explanation":"a simple object 一个简单的物件。"},{"q":"8","answer":"D","options":["losing","selling","hiding","using"],"explanation":"be using many such smart things 使用许多这样的智能物品。"},{"q":"9","answer":"A","options":["comfortable","empty","wrong","sorry"],"explanation":"more comfortable 更舒适。"},{"q":"10","answer":"B","options":["holiday","trouble","song","price"],"explanation":"no longer a trouble 不再是麻烦。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective1', 'U2', 'A Letter to My Future Self', 'Dear future me, I am writing this letter to (1)____ what your life might be like. By the time you read it, you will probably be (2)____ in a smart home that cooks and cleans by itself. I (3)____ that cars will drive themselves, so you will never need a (4)____ licence. Maybe you will have a job that does not even (5)____ today, working side by side with clever machines. I hope you have not learned to (6)____ change, but have chosen to welcome it instead. Remember that more technology does not always bring more (7)____; what matters is how wisely you use it. Keep a strong (8)____ on family and friends, just as we do now. I am a little (9)____ about the future, but mostly I feel excited. (10)____, I believe the years ahead will be full of fresh chances. Good luck — I am sure you will do well!', 153, 2, '[{"q":"1","answer":"C","options":["sell","throw","predict","lose"],"explanation":"predict what your life might be like 预测你的生活。"},{"q":"2","answer":"D","options":["selling","losing","hiding","living"],"explanation":"be living in a smart home 住在智能家居里。"},{"q":"3","answer":"A","options":["forecast","forget","refuse","deny"],"explanation":"I forecast that 我预测。"},{"q":"4","answer":"B","options":["song","driver''s","price","garden"],"explanation":"a driver''s licence 驾照。"},{"q":"5","answer":"C","options":["sleep","cry","exist","leave"],"explanation":"a job that does not exist today 今天还不存在的工作。"},{"q":"6","answer":"D","options":["enjoy","welcome","trust","resist"],"explanation":"learned to resist change 学会抵制改变。"},{"q":"7","answer":"A","options":["happiness","noise","price","weather"],"explanation":"more happiness 更多幸福。"},{"q":"8","answer":"B","options":["price","emphasis","garden","machine"],"explanation":"keep a strong emphasis on 重视。"},{"q":"9","answer":"C","options":["rich","late","worried","empty"],"explanation":"a little worried 有点担心。"},{"q":"10","answer":"D","options":["Because","Although","Unless","Nevertheless"],"explanation":"Nevertheless 尽管如此(句首副词)。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·对话 Talking About a Smart Home', '选择性必修一 U2 · dialogue', 3, 'Lucy: My family just moved into a smart home, and I love it.
