INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·短文 New Jobs for a New Age', '选择性必修一 U2 · passage', 2, 'Many people worry that smart machines will take away their jobs.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·对话 A Kitchen That Obeys Your Voice', '选择性必修一 U2 · dialogue', 3, 'Grace: Come and see my uncle''s new kitchen. It understands voice commands!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·短文 The Flight of the RoboBee', '选择性必修一 U2 · passage', 2, 'Today we look at a tiny flying robot called the RoboBee.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (11, 'A Letter to My Future Self(给未来自己的一封信:预测未来生活)', 'A Letter to My Future Self', '假设你叫李华。请用英语给未来的自己写一封约100词的信,预测你未来的生活,内容包括:① 科技将如何改变你的日常生活或工作(如智能家居/无人驾驶/AI);② 这些变化可能带来的一个好处和一个坏处;③ 你对未来的态度。注意:恰当使用将来进行时(will be doing)。', 'Suppose you are Li Hua. Write a letter (about 100 words) to your future self, predicting your future life. Include: 1) how technology will change your daily life or work (e.g. smart homes, driverless cars, AI); 2) one advantage and one disadvantage these changes may bring; 3) your attitude towards the future. Use the future progressive (will be doing) where it fits naturally.', '["预测未来生活(This time in 2050, you will be living in …)","一个好处 + 一个坏处(One good point is … ; the bad point is …)","对未来的态度(I look on the positive side and welcome change)","恰当使用将来进行时 will be doing"]'::jsonb, 70, 100, 'Dear Future Me, I am writing to imagine what your life will be like. By 2050, you will be living in a smart home that locks the doors, saves energy and cooks dinner all by itself. Every morning, a driverless car will be taking you to work while you read or rest. The good point is that technology will give you more free time and keep you secure. The bad point is that machines may sometimes go wrong, and that can be a scary prospect. Even so, I hope you will not resist these changes but welcome them. Look on the positive side! Best wishes, Li Hua', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["By 2050, you will be living in a smart home that cooks dinner all by itself.","Every morning, a driverless car will be taking you to work.","Technology will give you more free time and keep you secure.","I hope you will welcome these changes rather than resist them."]'::jsonb, '[{"wrong":"This time next year you will living in a smart home.","correct":"This time next year you will be living in a smart home.","note":"将来进行时是 will be + doing,不能少 be。"},{"wrong":"A driverless car will taking you to work.","correct":"A driverless car will be taking you to work.","note":"will 后接动词原形 be,再加 -ing。"},{"wrong":"I hope you will welcome these changes than resist them.","correct":"I hope you will welcome these changes rather than resist them.","note":"''宁愿……而不……''用 rather than。"}]'::jsonb, '【给未来自己的信结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (11, 'elective1', 'U2', '{"title":"将来进行时 will be doing 速查","intro":"将来进行时 = will be + 现在分词(doing),表示''将来某一时刻正在进行的动作''。判断口诀:句中有明确的将来时间点(this time tomorrow / at 9 am next Monday)、强调''届时正在进行'',就用 will be doing。","table":{"headers":["用法","说明 / 例句"],"rows":[["表将来某刻正在进行","This time next year, I will be studying abroad.(明年此时正在留学)"],["表预计必将发生","Most people will be travelling in driverless cars one day.(必将成趋势)"],["委婉询问安排","Will you be using the computer tonight?(比 Will you use… 更客气)"],["与 will do 对照","will do = 单纯将来动作;will be doing = 届时正在进行"]]},"specialRules":[{"rule":"结构固定:will be + V-ing,三部分缺一不可","mark":"will be having √ / will having ×"},{"rule":"靠将来时间状语判断:this time tomorrow / at 8 pm tonight / when you arrive tomorrow","mark":"有将来时间点+强调进行 → will be doing"},{"rule":"委婉询问对方计划时常用,语气比 will do 更礼貌","mark":"Will you be needing it? 你会要用它吗?"},{"rule":"与现在进行时 is doing 区别:is doing 说''此刻'',will be doing 说''将来某刻''","mark":"now is doing / tomorrow will be doing"}],"why":["将来进行时把镜头对准''将来的某一时刻'',强调那一刻动作正在进行(而非动作的开始或结束),所以一定要配一个明确的将来时间点;只说将来要做某事而不强调''正在进行''时,用一般将来时 will do 即可。"],"gaokaoPoints":["语法填空 / 完成句子高频:给将来时间状语 + 动词原形,填 will be doing。","辨析 will do(单纯将来)、is doing(现在/计划)、will be doing(将来进行)、will have done(将来完成)的区别。"],"examVsReal":[{"exam":"Will you be using the car tonight?(考试/书面更委婉)","real":"Are you using the car tonight?","note":"口语里现在进行时也常表将来计划,更随意"},{"exam":"This time tomorrow I will be flying to Beijing.(考试强调将来进行)","real":"Tomorrow I''m flying to Beijing.","note":"口语常用现在进行时表已定计划,省去 will be"}]}'::jsonb);
